import numpy as np

def r(x):
    return float(np.clip(x / 2.0, 0.0, 1.0))

def R(y_orig, y_new):
    e_orig = abs(float(y_orig) - 1.0)
    e_new = abs(float(y_new) - 1.0)
    if e_orig < 1e-15:
        return e_new < 1e-15
    ratio = e_new / e_orig
    return (0.5 ** 2.2) <= ratio <= (0.5 ** 1.8)
